(function(){const RA=globalThis.RA,D=(l,p)=>RA.D(l,p),E=(origin,prefix,root,suffix,source)=>({origin,prefix,root,suffix,source}),C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:"authored"}),M=(errorType,wrong,right,reason)=>({errorType,wrong,right,reason}),Q=(id,senseId,type,prompt,options,answer,explain,errorType)=>({id,senseId,type,prompt,options,answer,explain,errorType});
D("unstable",{etymology:E("Formed from un- + stable. Stable came through French from Latin stabilis, ‘firm or steady’; unstable can describe rapid change, a weak physical balance, disorder, or a structure liable to break apart and release radiation.", "un-","stable",null,null),contexts:[C("unstable.s1","政治","The coalition was unstable because two small parties could withdraw support at any time, making the government’s future hard to predict.","这个联合政府很不稳定，因为两个小党随时可能撤回支持，使政府的前景难以预测。","Unstable can mean changing often and quickly, so that events are hard to predict.","Predicative adjective after was; because explains why the coalition’s future is uncertain.","The government may change abruptly if either party withdraws.") ,C("unstable.s2","安全","The ladder looked unstable on the soft ground, so the workers secured its feet before climbing.","梯子立在松软地面上，看起来不稳，因此工人爬上去前固定了梯脚。","Unstable can mean not firmly fixed or balanced and liable to fail.","Predicative adjective after looked; so links the imbalance to the safety measure.","The ladder could shift or fall under a climber’s weight.") ,C("unstable.s3","冲突","Unstable borders triggered new conflicts when armed groups began disputing the checkpoints.","武装团体开始争夺检查站后，动荡的边界地区引发了新的冲突。","Unstable can describe a situation full of sudden trouble or public disorder.","Attributive adjective before borders; when introduces the event that turned tension into conflict.","The region is prone to abrupt political trouble and disorder.") ,C("unstable.s4","化学","The laboratory stored the unstable isotope behind shielding because it decayed quickly and emitted radiation.","实验室把这种不稳定同位素存放在屏蔽设施后，因为它衰变很快并释放辐射。","An unstable atomic nucleus or compound can break up and give off radiation.","Attributive adjective before isotope; because gives its decay and radiation as the reason for shielding.","The isotope’s structure changes and releases radiation.")],mistakes:[M("meaning","The unstable isotope had a stable structure, never decayed, and emitted no radiation throughout the test.","The stable isotope had a stable structure, never decayed, and emitted no radiation throughout the test.","A nucleus that does not decay or emit radiation in the test is not described as unstable in this sense.")],quiz:[Q("unstable.q1","unstable.s1","meaning","An unstable coalition is hard to predict because it ___.",["may change quickly when parties withdraw support","has a permanent majority that never shifts","has already completed its full term"],"may change quickly when parties withdraw support","Sense s1 concerns rapid, unpredictable change.","meaning"),Q("unstable.q2","unstable.s2","context","Which ladder is unstable? ",["One that wobbles on soft ground and may shift","One whose feet are secured on level flooring","One inspected and balanced on a firm surface"],"One that wobbles on soft ground and may shift","Sense s2 describes poor balance or insecure placement.","context"),Q("unstable.q3","unstable.s3","distinction","In “unstable borders triggered conflict,” what does unstable describe?",["A situation prone to sudden trouble and disorder","A ladder that is not level","An isotope that emits radiation"],"A situation prone to sudden trouble and disorder","Sense s3 applies to a political situation full of sudden conflict.","distinction"),Q("unstable.q4","unstable.s4","science","An unstable isotope may ___.",["decay and give off radiation","remain unchanged indefinitely with no radiation","be a political coalition"],"decay and give off radiation","Sense s4 concerns an atomic structure that breaks up and emits radiation.","meaning")]});
D("unsubstantiated",{etymology:E("Formed from un- + substantiated, the past participle of substantiate. Substantiate combines substance with -ate and means to support with evidence; unsubstantiated describes a claim stated without solid proof.", "un-","substantiate","-ed",null),contexts:[C("unsubstantiated.s1","新闻","The article repeated an unsubstantiated rumor about the mayor but offered no document or named witness to support it.","这篇文章重复了一则关于市长的未经证实的传闻，却没有提供文件或具名证人作为依据。","Unsubstantiated means stated without proof or solid evidence.","Attributive adjective before rumor; but contrasts the allegation with the missing supporting material.","The article provides no evidence to establish that the rumor is true.")],mistakes:[M("meaning","The allegation was unsubstantiated because two independent recordings and signed documents conclusively proved every detail.","The allegation was substantiated because two independent recordings and signed documents conclusively proved every detail.","Independent recordings and documents that prove the details substantiate the allegation.")],quiz:[Q("unsubstantiated.q1","unsubstantiated.s1","meaning","An unsubstantiated allegation is one ___.",["stated without solid supporting evidence","proved by several independent records","confirmed by a signed admission"],"stated without solid supporting evidence","The adjective means a statement lacks proof or solid evidence.","meaning"),Q("unsubstantiated.q2","unsubstantiated.s1","context","Which report relies on an unsubstantiated rumor? ",["One repeating a claim without a document or named witness","One quoting several verified records and witnesses","One correcting a claim after checking the source"],"One repeating a claim without a document or named witness","The claim has not been supported by solid evidence.","context"),Q("unsubstantiated.q3","unsubstantiated.s1","word-formation","Unsubstantiated is the negative form of ___.",["substantiated","unsettled","unsolicited"],"substantiated","Un- negates the participle substantiated.","word-formation"),Q("unsubstantiated.q4","unsubstantiated.s1","distinction","Does unsubstantiated necessarily mean a claim has been proved false?",["No; it means proof has not been supplied","Yes; it means every detail was disproved","Yes; it means the claim was never spoken"],"No; it means proof has not been supplied","Lack of supporting evidence is different from evidence of falsity.","distinction")]});
D("unsuccessful",{etymology:E("Formed from un- + successful. Success came through French from Latin successus, ‘a following or result’; unsuccessful means failing to achieve the intended result.", "un-","success","-ful",null),contexts:[C("unsuccessful.s1","法律","The appeal was unsuccessful because the court found no new evidence that could change the original ruling.","上诉未能成功，因为法院没有发现任何足以改变原判的新证据。","Unsuccessful means failing to achieve the intended result.","Predicative adjective after was; because states why the desired reversal did not occur.","The appeal did not change the judgment it challenged.")],mistakes:[M("meaning","The unsuccessful rescue reached every missing climber before nightfall and brought the entire team back safely.","The successful rescue reached every missing climber before nightfall and brought the entire team back safely.","A rescue that achieves its objective is successful, not unsuccessful.")],quiz:[Q("unsuccessful.q1","unsuccessful.s1","meaning","An unsuccessful attempt ___.",["fails to achieve its intended result","reaches its goal exactly as planned","has no intended result at all"],"fails to achieve its intended result","Unsuccessful is the negative of successful and marks failure to reach a goal.","meaning"),Q("unsuccessful.q2","unsuccessful.s1","context","Which appeal was unsuccessful? ",["One that left the original ruling unchanged","One that overturned the ruling in the appellant’s favor","One that obtained the requested remedy"],"One that left the original ruling unchanged","The appeal failed to produce its intended result.","context"),Q("unsuccessful.q3","unsuccessful.s1","word-formation","Which suffix forms successful from success? ",["-ful","-less","-ly"],"-ful","Success + -ful forms successful; un- then negates it.","word-formation"),Q("unsuccessful.q4","unsuccessful.s1","distinction","Can an unsuccessful project still teach useful lessons?",["Yes; failure to reach the goal does not erase what was learned","No; it means no work was done","No; it means the project was unregistered"],"Yes; failure to reach the goal does not erase what was learned","Failure to achieve a goal does not mean the effort taught nothing.","distinction")]});
D("unsuitable",{etymology:E("Formed from un- + suitable. Suitable comes through French from Latin subire, ‘come up to’; unsuitable means not appropriate or fitting for a particular purpose or setting.","un-","suit","-able",null),contexts:[C("unsuitable.s1","户外","Sandals were unsuitable for the rocky hike, so the group changed into boots before leaving the trailhead.","凉鞋不适合走多石的山路，因此一行人在离开步道入口前换上了靴子。","Unsuitable means not appropriate or fitting for a purpose or situation.","Predicative adjective after were; so introduces the practical change made in response.","Footwear without protection is a poor fit for the rocky route.")],mistakes:[M("meaning","The thin sandals were unsuitable for the rocky hike because they provided excellent ankle support and protected the feet from sharp stones.","The thin sandals were suitable for the rocky hike because they provided excellent ankle support and protected the feet from sharp stones.","Footwear that protects the feet and supports the ankles is suitable for the hike.")],quiz:[Q("unsuitable.q1","unsuitable.s1","meaning","An unsuitable tool is one that ___.",["does not fit the task or conditions","is designed for the task and works well","has been selected for its exact purpose"],"does not fit the task or conditions","The adjective means not appropriate or fitting.","meaning"),Q("unsuitable.q2","unsuitable.s1","context","Which shoes are unsuitable for a rocky hike?",["Thin sandals with no grip or toe protection","Sturdy boots with protective soles","Hiking shoes tested on the same trail"],"Thin sandals with no grip or toe protection","The terrain calls for footwear that protects and grips.","context"),Q("unsuitable.q3","unsuitable.s1","word-formation","Which prefix makes suitable negative?",["un-","re-","pre-"],"un-","Un- negates suitable to make unsuitable.","word-formation"),Q("unsuitable.q4","unsuitable.s1","distinction","Can an item be suitable for one purpose but unsuitable for another?",["Yes; suitability depends on the task or setting","No; the adjective is permanent for every use","No; it describes only a person’s manners"],"Yes; suitability depends on the task or setting","An item may fit one use while failing another.","distinction")]});
D("unsullied",{etymology:E("Formed from un- + sullied, the past participle of sully. Sully is an old English verb meaning to stain or damage; unsullied describes a reputation or condition that remains pure and undamaged.","un-","sully","-ed",null),contexts:[C("unsullied.s1","名誉","After the audit, the archivist left office with an unsullied reputation because no record showed that she had altered a document.","审计结束后，这位档案管理员声誉未受玷污地离职，因为没有记录显示她改动过文件。","Unsullied means pure and undamaged in reputation or condition.","Adverbial complement after left office; because explains why the archivist’s reputation remains clean.","The investigation found no misconduct to stain her record.")],mistakes:[M("meaning","The official’s unsullied reputation was ruined by proven bribery and falsified records throughout the investigation.","The official’s sullied reputation was ruined by proven bribery and falsified records throughout the investigation.","Proven bribery and falsification damage a reputation, so it is sullied.")],quiz:[Q("unsullied.q1","unsullied.s1","meaning","An unsullied reputation is one that is ___.",["not stained by wrongdoing","damaged by proven misconduct","known to be false"],"not stained by wrongdoing","The source sense describes a reputation that remains undamaged.","meaning"),Q("unsullied.q2","unsullied.s1","context","Which official has an unsullied record?",["One whose audit found no evidence of misconduct","One convicted of falsifying every report","One whose reputation was damaged by proven bribery"],"One whose audit found no evidence of misconduct","No finding of misconduct leaves the record unsullied.","context"),Q("unsullied.q3","unsullied.s1","word-formation","Un-sullied means a reputation is ___.",["not stained or damaged","covered in a literal stain only","newly registered"],"not stained or damaged","The negative prefix reverses sullied.","word-formation"),Q("unsullied.q4","unsullied.s1","distinction","Does unsullied describe only physical cleanliness?",["No; it can describe an unblemished reputation","Yes; it applies only to polished metal","Yes; it means never seen"],"No; it can describe an unblemished reputation","The source entry explicitly applies to reputation as well as condition.","distinction")]});
D("unsung",{etymology:E("Formed from un- + sung, the past participle of sing. In the established adjective, sung extends to public praise: an unsung person has not been celebrated or recognized for a contribution.","un-","sing","-ung",null),contexts:[C("unsung.s1","团队","The night custodian was the unsung hero of the exhibition, quietly repairing display lights before visitors arrived each morning.","夜班管理员是展览中默默无闻的功臣，每天早晨访客到来前都悄悄修好展柜灯光。","Unsung means not celebrated in song or public praise.","Attributive phrase before hero; the following clause shows the valuable work that receives little notice.","The custodian contributes greatly without public recognition.")],mistakes:[M("meaning","The unsung volunteer was praised on national television and received a public award for every shift she worked.","The celebrated volunteer was praised on national television and received a public award for every shift she worked.","Repeated public praise and awards mean the volunteer is celebrated rather than unsung.")],quiz:[Q("unsung.q1","unsung.s1","meaning","An unsung contributor is someone ___.",["whose work has not received public praise","who has received a widely publicized award","who performs no useful work"],"whose work has not received public praise","The adjective describes a contribution that is not celebrated.","meaning"),Q("unsung.q2","unsung.s1","context","Which worker is an unsung hero?",["A cleaner whose careful work keeps the museum open but is rarely acknowledged","A director whose work is praised in every newspaper","A guest who receives an award for speaking at the opening"],"A cleaner whose careful work keeps the museum open but is rarely acknowledged","The person contributes but has not received public recognition.","context"),Q("unsung.q3","unsung.s1","distinction","Does unsung mean a person literally cannot sing?",["No; it means the person has not been celebrated or praised","Yes; it describes a singer who lost their voice","Yes; it means the person has no name"],"No; it means the person has not been celebrated or praised","The adjective is figurative, extending sung to recognition.","distinction"),Q("unsung.q4","unsung.s1","word-choice","The volunteers were the ____ people who made the event possible without recognition.",["unsung","unsullied","unspecified"],"unsung","They contributed without being publicly praised.","word-choice")]});
D("unsure",{etymology:E("Formed from un- + sure. Sure came through French from Latin securus, ‘free from care’; unsure describes not knowing what is true or likely and also lacking confidence to act or decide.","un-","sure",null,null),contexts:[C("unsure.s1","知识","I am unsure whether the museum opens on Monday, so I will check its current schedule before we travel.","我不确定博物馆星期一是否开放，因此出发前会查看它的最新时间表。","Unsure can mean not knowing what is true or what will happen.","Predicative adjective after am; so introduces the sensible response to missing information.","The speaker lacks reliable information about the opening day.") ,C("unsure.s2","信心","The new violinist felt unsure of herself during the audition, although she had practised the piece carefully.","这位新小提琴手在试演时对自己缺乏信心，尽管她已经认真练习过曲子。","Unsure can mean not confident enough to act or decide.","Predicative adjective after felt; although contrasts her preparation with her remaining lack of confidence.","She knows the piece but doubts her ability to perform it well.")],mistakes:[M("meaning","He was unsure of himself, so he confidently volunteered to lead the first demonstration without hesitation.","He was confident in himself, so he volunteered to lead the first demonstration without hesitation.","Confidently volunteering without hesitation signals confidence rather than self-doubt.")],quiz:[Q("unsure.q1","unsure.s1","meaning","If you are unsure whether a train runs today, you ___.",["do not know the fact with confidence","know its schedule with certainty","have already boarded it"],"do not know the fact with confidence","Sense s1 is uncertainty about what is true or will happen.","meaning"),Q("unsure.q2","unsure.s2","context","Which musician feels unsure of herself?",["One who doubts her ability to perform despite practising","One who performs confidently before a large audience","One who decides immediately and without hesitation"],"One who doubts her ability to perform despite practising","Sense s2 concerns lack of confidence rather than lack of information.","context"),Q("unsure.q3","unsure.s1","distinction","Can someone be unsure about a fact but confident about speaking?",["Yes; uncertainty about information differs from confidence to act","No; both senses always describe physical danger","No; the two uses are identical in every detail"],"Yes; uncertainty about information differs from confidence to act","The entry separates not knowing from lacking confidence.","distinction"),Q("unsure.q4","unsure.s2","word-choice","She was ____ about signing the contract and asked for another day to think.",["unsure","unsung","unspoiled"],"unsure","Hesitation before deciding shows a lack of confidence.","word-choice")]});
D("unsureness",{etymology:E("Formed from unsure + -ness, the English suffix that makes a noun naming a state or quality; unsureness is the state of not being sure.",null,"unsure","-ness",null),contexts:[C("unsureness.s1","访谈","A brief unsureness in his first answers disappeared once the interviewer clarified what the question meant.","采访者解释清楚问题的意思后，他最初回答中的些许不确定便消失了。","Unsureness is the state of not being sure or lacking confidence.","Subject noun followed by disappeared; once introduces the point at which uncertainty ended.","His initial answers show uncertainty that clarification resolves.")],mistakes:[M("meaning","Her unsureness about the route meant she knew every turn exactly and needed no map or directions.","Her certainty about the route meant she knew every turn exactly and needed no map or directions.","Knowing every turn exactly is certainty, the opposite of unsureness.")],quiz:[Q("unsureness.q1","unsureness.s1","meaning","Unsureness is ___.",["a state of not being sure","complete certainty about a fact","a request made without being asked"],"a state of not being sure","The noun names the condition of lacking certainty or confidence.","meaning"),Q("unsureness.q2","unsureness.s1","context","Which speaker shows unsureness?",["One who hesitates because the answer may be wrong","One who states the verified answer without doubt","One who reads a signed certificate aloud"],"One who hesitates because the answer may be wrong","Hesitation about whether an answer is correct shows unsureness.","context"),Q("unsureness.q3","unsureness.s1","word-formation","Which suffix turns unsure into the noun unsureness?",["-ness","-ly","-able"],"-ness","The suffix -ness forms a noun for a state or quality.","word-formation"),Q("unsureness.q4","unsureness.s1","distinction","Is unsureness the same as a proven mistake?",["No; it is uncertainty, whether or not the person is actually mistaken","Yes; it means the answer is definitely false","Yes; it means a claim was publicly praised"],"No; it is uncertainty, whether or not the person is actually mistaken","A person can feel unsure even when their answer turns out to be correct.","distinction")]});
D("unsuspected",{etymology:E("Formed from un- + suspected, the past participle of suspect. Suspect came through French from Latin suspicere, ‘look up at or mistrust’; unsuspected describes something true or present that people had not thought of.", "un-","suspect","-ed",null),contexts:[C("unsuspected.s1","人物","The diary revealed an unsuspected sense of humor in the reserved judge, who had filled its margins with comic sketches.","这本日记显露出这位沉默法官不为人知的幽默感，他在页边画满了滑稽草图。","Unsuspected means not suspected or expected to exist.","Attributive adjective before sense of humor; who gives evidence that surprises readers.","The quality was present but others had not imagined it.")],mistakes:[M("meaning","Her suspected talent surprised everyone because nobody had known or expected it before the performance.","Her unsuspected talent surprised everyone because nobody had known or expected it before the performance.","A quality nobody had imagined or expected is unsuspected, not already suspected.")],quiz:[Q("unsuspected.q1","unsuspected.s1","meaning","An unsuspected quality is one that ___.",["was present but people had not thought it existed","had already been identified by everyone","was publicly announced in advance"],"was present but people had not thought it existed","The adjective describes something true or present that was not suspected.","meaning"),Q("unsuspected.q2","unsuspected.s1","context","Which discovery reveals an unsuspected skill? ",["A quiet clerk turns out to be an accomplished pianist, surprising colleagues","A musician performs the skill advertised on every poster","A teacher explains a skill that the student demonstrated yesterday"],"A quiet clerk turns out to be an accomplished pianist, surprising colleagues","The ability existed but had not been expected by colleagues.","context"),Q("unsuspected.q3","unsuspected.s1","distinction","Does unsuspected mean that the quality is imaginary?",["No; it can be real even though people did not expect it","Yes; it means a rumor has been disproved","Yes; it means people saw it every day"],"No; it can be real even though people did not expect it","The entry says the quality exists without people thinking so.","distinction"),Q("unsuspected.q4","unsuspected.s1","word-formation","Which prefix negates suspected? ",["un-","re-","pre-"],"un-","Un- forms the adjective meaning not suspected.","word-formation")]});
D("unsuspecting",{etymology:E("Formed from un- + suspecting, the present participle of suspect. It describes someone who does not realize that something is wrong or harmful.", "un-","suspect","-ing",null),contexts:[C("unsuspecting.s1","网络安全","The phishing page copied the bank’s logo and fooled unsuspecting users into entering their passwords.","钓鱼网页仿造了银行标志，骗得毫无戒心的用户输入密码。","Unsuspecting means not realizing that something is wrong or harmful.","Attributive adjective before users; into introduces the harmful action they were tricked into taking.","The users do not recognize the page as a threat.")],mistakes:[M("meaning","The unsuspecting visitor recognized the fake payment page immediately and closed it before entering any details.","The suspicious visitor recognized the fake payment page immediately and closed it before entering any details.","A person who detects a threat is not unsuspecting in that situation.")],quiz:[Q("unsuspecting.q1","unsuspecting.s1","meaning","An unsuspecting user is someone who ___.",["does not realize a threat may be present","has already identified the scam","created the harmful page deliberately"],"does not realize a threat may be present","The adjective describes someone unaware that something is wrong or harmful.","meaning"),Q("unsuspecting.q2","unsuspecting.s1","context","Which person is an unsuspecting target? ",["A customer who enters details on a convincing fake site","A customer who spots the false address and leaves","A security analyst who created the warning"],"A customer who enters details on a convincing fake site","The target does not realize that the page is harmful.","context"),Q("unsuspecting.q3","unsuspecting.s1","distinction","Is an unsuspecting person necessarily careless?",["No; the person may simply not know a danger is present","Yes; the word means intentionally dishonest","Yes; it means the person is not registered"],"No; the person may simply not know a danger is present","The word describes lack of suspicion, not blame or intent.","distinction"),Q("unsuspecting.q4","unsuspecting.s1","word-formation","Unsuspecting is formed from un- plus the present participle of ___.",["suspect","specify","settle"],"suspect","Suspecting is the -ing form of suspect.","word-formation")]});
D("unswerving",{etymology:E("Formed from un- + swerving, the present participle of swerve, from Old English sweorfan, ‘turn aside’; unswerving describes support or commitment that does not turn away from its person or goal.", "un-","swerve","-ing",null),contexts:[C("unswerving.s1","团队","She gave the rescue project unswerving support, returning each day despite setbacks and long delays.","尽管遭遇挫折和长期延误，她仍始终如一地支持救援项目，每天都回来继续工作。","Unswerving means not turning aside from a person, aim, or course.","Attributive adjective before support; despite contrasts her steady commitment with the setbacks.","Her backing does not weaken or change direction.")],mistakes:[M("meaning","His unswerving support vanished as soon as the first minor obstacle appeared, and he immediately abandoned the project.","His wavering support vanished as soon as the first minor obstacle appeared, and he immediately abandoned the project.","Support that disappears at the first obstacle is wavering rather than unswerving.")],quiz:[Q("unswerving.q1","unswerving.s1","meaning","Unswerving support is support that ___.",["remains firm and does not turn away","ends after the first setback","changes sides whenever the goal becomes difficult"],"remains firm and does not turn away","The adjective describes commitment that does not turn aside.","meaning"),Q("unswerving.q2","unswerving.s1","context","Which volunteer shows unswerving commitment? ",["One who continues the work through setbacks","One who leaves whenever progress slows","One who supports the goal only while it is popular"],"One who continues the work through setbacks","Continuing despite difficulty shows steady commitment.","context"),Q("unswerving.q3","unswerving.s1","distinction","Does unswerving mean support can never be reconsidered? ",["No; it describes steady commitment, not a ban on reasoned change","Yes; it means ignoring all evidence","Yes; it means an action was never spoken"],"No; it describes steady commitment, not a ban on reasoned change","The adjective concerns constancy, not whether new facts should be considered.","distinction"),Q("unswerving.q4","unswerving.s1","word-choice","The team relied on her ____ dedication during the long recovery effort.",["unswerving","unsuspected","untapped"],"unswerving","Her dedication remains steady despite the long effort.","word-choice")]});
D("untamed",{etymology:E("Formed from un- + tamed, the past participle of tame, which continues Old English tam; untamed describes an animal not trained to live with people and a strong character difficult to control.", "un-","tame","-ed",null),contexts:[C("untamed.s1","野生动物","A herd of untamed horses crossed the valley at dawn, keeping clear of the fenced ranch and its riders.","一群未驯化的野马在黎明时穿过山谷，避开围栏牧场和骑手。","Untamed can mean living in a wild state and not trained to live with people.","Attributive adjective before horses; keeping clear shows their distance from human control.","The horses remain wild rather than domesticated.") ,C("untamed.s2","个性","Even after years in the city, the singer kept an untamed spirit and refused to let convention choose her songs.","即使在城市生活多年，这位歌手仍保有奔放不羁的个性，不让陈规替她选择歌曲。","Untamed can describe a strong, free character that is difficult to control.","Attributive adjective before spirit; and links the independent character with her refusal to follow convention.","Her personality remains vigorous and resistant to control.")],mistakes:[M("meaning","The untamed horse had been carefully trained to live indoors, obey every command, and accept a rider calmly.","The tame horse had been carefully trained to live indoors, obey every command, and accept a rider calmly.","Training that makes an animal comfortable living with people makes it tame.")],quiz:[Q("untamed.q1","untamed.s1","meaning","An untamed horse is one that ___.",["lives wild and has not been trained to live with people","has been trained to obey a rider","lives safely in a stable with its trainer"],"lives wild and has not been trained to live with people","Sense s1 concerns an animal not domesticated or trained.","meaning"),Q("untamed.q2","untamed.s2","context","Which person has an untamed spirit? ",["Someone with a strong independent character resistant to control","Someone who follows every fashion without question","Someone who has never seen a wild animal"],"Someone with a strong independent character resistant to control","Sense s2 describes a free and difficult-to-control character.","context"),Q("untamed.q3","untamed.s1","distinction","Does untamed mean the animal is necessarily dangerous?",["No; it means it is wild and not trained to live with people","Yes; every untamed animal attacks people","Yes; it means the animal is sick"],"No; it means it is wild and not trained to live with people","The definition concerns domestication, not a guaranteed aggressive nature.","distinction"),Q("untamed.q4","untamed.s2","word-choice","The writer kept an ____ independence and resisted every imposed role.",["untamed","unspoken","unregistered"],"untamed","The adjective describes a strong character that resists control.","word-choice")]});
D("untapped",{etymology:E("Formed from un- + tapped, the past participle of tap, ‘draw from or make use of’; untapped describes a resource, market, or ability that has not yet been used.", "un-","tap","-ed",null),contexts:[C("untapped.s1","资源","The region’s untapped geothermal energy could supply nearby towns if engineers complete the feasibility study.","如果工程师完成可行性研究，该地区尚未开发的地热能就能为附近城镇供电。","Untapped means not yet exploited or made use of, especially of a resource or potential.","Attributive adjective before energy; if introduces the condition needed to put the resource to use.","The geothermal source exists but has not yet been developed.")],mistakes:[M("meaning","The untapped reserve had been fully extracted and every usable deposit was already exhausted.","The depleted reserve had been fully extracted and every usable deposit was already exhausted.","A resource that has been completely extracted is no longer untapped.")],quiz:[Q("untapped.q1","untapped.s1","meaning","An untapped resource is one that ___.",["has not yet been used or exploited","has already been completely extracted","has no possible value or use"],"has not yet been used or exploited","The adjective describes a resource that remains unused.","meaning"),Q("untapped.q2","untapped.s1","context","Which talent is untapped? ",["A skill no one has yet developed or used","A skill used professionally for many years","A skill demonstrated in every performance"],"A skill no one has yet developed or used","Untapped also applies to ability that has not been put to use.","context"),Q("untapped.q3","untapped.s1","distinction","Does untapped mean a resource does not exist?",["No; it exists but has not yet been exploited","Yes; it means the resource is imaginary","Yes; it means the resource has been used up"],"No; it exists but has not yet been exploited","The word implies potential still available to be used.","distinction"),Q("untapped.q4","untapped.s1","word-formation","Untapped is formed from un- and the past participle of ___.",["tap","tame","tie"],"tap","Tap can mean to draw on or make use of a resource.","word-formation")]});
D("untie",{etymology:E("Formed from un- + tie. Tie goes back to Old English tīgan, ‘bind’; untie means undo a knot or bow and can also release a boat or animal by loosening its rope.", "un-","tie",null,null),contexts:[C("untie.s1","日常","Mara untied the ribbon carefully so she could lift the box lid without tearing the gift wrapping.","玛拉小心解开丝带，这样就能掀开盒盖而不撕破礼品包装。","Untie can mean undo a knot, string, or bow fastening something.","The verb takes the ribbon as object; so introduces the purpose of loosening it carefully.","She releases the bow that holds the wrapping closed.") ,C("untie.s2","航海","Before dawn, the deckhand untied the boat from the jetty and checked that the channel was clear.","黎明前，甲板水手解开系在码头上的船，并检查航道是否畅通。","Untie can mean release a boat or animal by loosening its securing rope.","The verb takes the boat as object; from the jetty identifies what held it in place.","Loosening the rope frees the boat to leave the dock.")],mistakes:[M("meaning","She untied the bow by pulling the knot tighter and fastening it more firmly around the parcel.","She tied the bow by pulling the knot tighter and fastening it more firmly around the parcel.","Tightening and fastening a knot ties it rather than unties it.")],quiz:[Q("untie.q1","untie.s1","meaning","To untie a bow is to ___.",["undo the knot that fastens it","tighten it around a package","cut the ribbon into pieces"],"undo the knot that fastens it","Sense s1 means undoing a knot, string, or bow.","meaning"),Q("untie.q2","untie.s2","context","Which action unties a boat? ",["A deckhand loosens its rope from the jetty","A deckhand secures its rope tightly to a post","A deckhand paints its name on the hull"],"A deckhand loosens its rope from the jetty","Sense s2 is releasing a boat by loosening the line that holds it.","context"),Q("untie.q3","untie.s1","distinction","Does untie mean to cut a bow apart? ",["No; it means undo the fastening, usually leaving the string intact","Yes; it means destroy every part of the ribbon","Yes; it means tie a stronger knot"],"No; it means undo the fastening, usually leaving the string intact","The action releases the knot or bow rather than cutting it.","distinction"),Q("untie.q4","untie.s2","word-choice","The sailor had to ____ the horse from the post before leading it away.",["untie","unveil","untap"],"untie","Loosening the rope releases the animal from where it is secured.","word-choice")]});
D("until",{etymology:E("From Old English untill, a compound of un- and till; till is related to Old Norse til, ‘to’. Until marks an endpoint in time, either as a preposition or conjunction.",null,"till",null,null),contexts:[C("until.s1","时间","The reading room stays open until nine, and staff begin closing the doors immediately afterward.","阅览室开放到九点，之后工作人员立即开始关门。","As a preposition, until means up to a stated time and not after it.","Until nine sets the endpoint of stays open; afterward confirms that the time is a boundary.","Nine is the latest time the room remains open.") ,C("until.s2","时间","Nora did not submit the form until Friday, although the deadline had been posted on Monday.","诺拉直到星期五才提交表格，尽管截止日期星期一就已经公布。","With a negative clause, until can mean not before the stated time.","Did not submit ... until Friday places the action no earlier than Friday; although adds the earlier deadline.","The submission happened on Friday, not before.") ,C("until.s3","时间","Wait by the gate until the caretaker returns, then follow her to the office.","在门口等到管理员回来，然后跟她去办公室。","As a conjunction, until can mean up to the time that another event happens.","Until introduces the clause the caretaker returns; then marks the next action after that event.","The waiting continues up to the caretaker’s return.")],mistakes:[M("meaning","The room closed until nine, meaning it was open throughout the morning and afternoon before nine.","The room stayed open until nine, meaning it was open throughout the morning and afternoon before nine.","Until nine marks the endpoint of an ongoing state; closed until nine would mean it was not open before then.")],quiz:[Q("until.q1","until.s1","grammar","In “The desk is staffed until six,” until introduces ___.",["the endpoint time of the staffing","the person who staffs the desk","the reason the desk was built"],"the endpoint time of the staffing","Here until is a preposition marking how long the desk remains staffed.","grammar"),Q("until.q2","until.s2","meaning","“He did not call until noon” means he called ___.",["at noon or later, but not before noon","before noon and never afterward","at midnight rather than at noon"],"at noon or later, but not before noon","With a negative clause, until means not before that time.","meaning"),Q("until.q3","until.s3","context","Which sentence uses until to introduce an event clause? ",["Stay here until the lights turn green.","The shop closes at six.","Until noon, no buses arrived."],"Stay here until the lights turn green.","The clause after until names an event that ends the waiting.","context"),Q("until.q4","until.s1","distinction","Does until nine normally include time after nine? ",["No; it marks nine as the endpoint, not a later period","Yes; it means the room stays open indefinitely","Yes; it means the room opens at nine"],"No; it marks nine as the endpoint, not a later period","Until identifies the limit of the stated time interval.","distinction")]});
D("until now",{etymology:E("A phrase formed from until + now, with now naming the present moment; until now marks the period up to this moment and often signals that circumstances may change afterward.",null,"until + now",null,null),contexts:[C("until now.s1","进展","Until now, nobody had requested access to the archive, but the new research team filed an application this morning.","直到现在，还没有人申请查阅档案，但新的研究团队今天早晨提交了申请。","Until now means up to this moment, often with a change following.","The opening phrase sets the earlier period; but contrasts it with the new application this morning.","No request existed before the present change.")],mistakes:[M("meaning","Until now, the team has never had a key, although it has held one for the entire year before today.","Until now, the team has never had a key; it received one today.","Until now marks the period before the current change, not the entire past year in which the team already held a key.")],quiz:[Q("until now.q1","until now.s1","meaning","Until now refers to ___.",["the period up to this present moment","a point that will happen next year","an event that occurred only in the past"],"the period up to this present moment","The phrase means up to the current moment.","meaning"),Q("until now.q2","until now.s1","context","Which report uses until now naturally? ",["Until now, the bridge had remained closed; today it reopened.","Until now, tomorrow’s meeting has already finished.","Until now, the bridge will have opened next year."],"Until now, the bridge had remained closed; today it reopened.","The phrase marks a previous state that changes in the present.","context"),Q("until now.q3","until now.s1","distinction","Does until now always mean that nothing can change after this moment?",["No; it often introduces a change that is happening now","Yes; it means the situation is permanent","Yes; it refers only to the distant past"],"No; it often introduces a change that is happening now","The phrase can mark the point before a new event or state.","distinction"),Q("until now.q4","until now.s1","word-choice","____, no one had asked to inspect the file; a request arrived today.",["Until now","Untimely","Untamed"],"Until now","The phrase correctly marks the prior period ending at today’s change.","word-choice")]});
D("untimely",{etymology:E("Formed from un- + timely, from time + -ly. The adjective means arriving at a bad moment or earlier than expected, especially when describing a death.", "un-","time","-ly",null),contexts:[C("untimely.s1","活动","An untimely storm ended the outdoor match before the final set could begin.","一场来得不是时候的暴风雨使户外比赛在决胜盘开始前就结束了。","Untimely means occurring at a bad moment or earlier than expected.","Attributive adjective before storm; before marks the interruption of the scheduled final set.","The storm arrives at a moment that disrupts the event.")],mistakes:[M("meaning","The untimely rain arrived exactly when the outdoor match had ended and caused no interruption to play.","The timely rain arrived after the outdoor match had ended and caused no interruption to play.","Rain after the event causes no poorly timed interruption; untimely does not fit.")],quiz:[Q("untimely.q1","untimely.s1","meaning","An untimely interruption happens ___.",["at a bad moment or earlier than expected","at exactly the planned and convenient moment","only after everyone has left"],"at a bad moment or earlier than expected","The adjective concerns poor timing or an event arriving too early.","meaning"),Q("untimely.q2","untimely.s1","context","Which event is untimely? ",["A storm stops the outdoor final before it begins","A scheduled break occurs at the announced time","A delivery arrives during the agreed window"],"A storm stops the outdoor final before it begins","The weather interrupts the event at a particularly bad moment.","context"),Q("untimely.q3","untimely.s1","distinction","Does untimely always mean that an event was unexpected?",["No; it means poorly timed or early, even if it was anticipated","Yes; it means nobody could predict it","Yes; it means the event was not registered"],"No; it means poorly timed or early, even if it was anticipated","Timing can be untimely even when the event itself was expected.","distinction"),Q("untimely.q4","untimely.s1","word-choice","The meeting’s ____ cancellation left the visitors waiting outside.",["untimely","unsullied","unselfish"],"untimely","The cancellation happens at a bad moment for the visitors.","word-choice")]});
D("untold",{etymology:E("Formed from un- + told, the past participle of tell. Untold can mean too great in amount to count or measure and, of stories or facts, never told or made known.", "un-","tell","-ed",null),contexts:[C("untold.s1","灾害","The flood caused untold damage across the valley, destroying homes and roads faster than crews could assess the loss.","洪水在整个山谷造成了难以估量的损失，房屋和道路被毁的速度超过了救援人员评估损失的速度。","Untold can mean so great in amount that it cannot be counted or measured.","Attributive adjective before damage; the following clause illustrates its vast scale.","The damage is enormous and not readily measurable.") ,C("untold.s2","历史","The old photographs preserve untold stories of the workers whose names never appeared in the company records.","这些旧照片保存着未曾讲述的工人故事，他们的名字从未出现在公司的档案里。","Untold can mean never told or made known to others.","Attributive adjective before stories; whose clause explains why the accounts remained unknown.","The workers’ experiences were never recorded or shared publicly.")],mistakes:[M("meaning","The untold story had been narrated in detail at every public meeting and published in several widely read books.","The well-known story had been narrated in detail at every public meeting and published in several widely read books.","Repeated public narration and publication mean the story is not untold.")],quiz:[Q("untold.q1","untold.s1","meaning","Untold suffering can mean suffering ___.",["too great to count or measure","already counted exactly in a short list","that never happened"],"too great to count or measure","Sense s1 conveys an amount too large to measure.","meaning"),Q("untold.q2","untold.s2","context","Which story is untold? ",["A worker’s experience never recorded or shared","A memoir published in several editions","A story retold at every public meeting"],"A worker’s experience never recorded or shared","Sense s2 describes something never made known to others.","context"),Q("untold.q3","untold.s1","distinction","Does untold suffering always mean nobody has suffered?",["No; it can mean the amount is too great to measure","Yes; it means the suffering is imaginary","Yes; it means the story has been widely published"],"No; it can mean the amount is too great to measure","The adjective has a quantitative sense as well as the sense ‘not narrated.’","distinction"),Q("untold.q4","untold.s2","word-choice","The archive revealed ____ accounts of the workers’ lives that had never been shared.",["untold","unseasonable","unsuitable"],"untold","The accounts were not previously narrated or made known.","word-choice")]});
D("untouched",{etymology:E("Formed from un- + touched, the past participle of touch, from Old French tochier; untouched describes something no one has handled, something unaffected or undamaged, and food that has not been eaten.", "un-","touch","-ed",null),contexts:[C("untouched.s1","档案","The sealed parcel sat untouched on the archive shelf until a conservator could examine its fragile wrapping.","密封包裹一直原封不动地放在档案架上，直到修复人员能够检查易碎的包装。","Untouched can mean not handled by anyone.","Predicative adjective after sat; until marks the point at which handling may begin.","No one has opened or handled the parcel.") ,C("untouched.s2","灾害","The village remained untouched by the storm, although farms on the exposed coast suffered severe damage.","尽管暴露在海岸上的农场遭受严重破坏，这座村庄仍未受风暴影响。","Untouched can mean not changed, damaged, or affected by an event.","Predicative adjective after remained; although contrasts the village with damaged farms.","The storm did not alter or harm the village.") ,C("untouched.s3","餐饮","His dinner remained untouched because he felt too anxious to eat before the examination results arrived.","他的晚餐一口未动，因为考试结果公布前他焦虑得吃不下。","Untouched can describe food not eaten because someone has no appetite or leaves it.","Predicative adjective after remained; because explains why none of the food was eaten.","The meal is still there because the diner did not eat it.")],mistakes:[M("meaning","The untouched meal was completely eaten by the guest, and the empty plate was cleared before dessert.","The finished meal was completely eaten by the guest, and the empty plate was cleared before dessert.","Food that has been eaten is not untouched.")],quiz:[Q("untouched.q1","untouched.s1","meaning","An untouched package is one that ___.",["no one has handled or opened","has been opened and repacked several times","has been eaten by a guest"],"no one has handled or opened","Sense s1 describes something not touched or handled.","meaning"),Q("untouched.q2","untouched.s2","context","Which village was untouched by the storm? ",["One with no damage or change from the storm","One whose roofs were torn away by the wind","One flooded by the storm surge"],"One with no damage or change from the storm","Sense s2 means not affected or damaged by an event.","context"),Q("untouched.q3","untouched.s3","meaning","An untouched dinner is dinner that ___.",["has not been eaten","was served at the correct temperature","was carried to the table"],"has not been eaten","Sense s3 applies to food left uneaten.","meaning"),Q("untouched.q4","untouched.s2","distinction","Can an untouched village be near a storm-damaged coast?",["Yes; it may remain unaffected while nearby places are damaged","No; every nearby place must have identical damage","No; untouched only describes uneaten food"],"Yes; it may remain unaffected while nearby places are damaged","The adjective describes the village’s condition, not every nearby location.","distinction")]});
D("untraditional",{etymology:E("Formed from un- + traditional. Traditional comes from tradition + -al, with tradition from Latin traditio, ‘handing over’; untraditional describes a departure from custom or an established style.", "un-","tradition","-al",null),contexts:[C("untraditional.s1","教育","The school adopted untraditional teaching methods, replacing long lectures with student-led experiments and field observations.","这所学校采用了不合传统的教学方法，用学生主导的实验和实地观察取代了长篇讲授。","Untraditional means departing from a custom, style, or established way.","Attributive adjective before teaching methods; the participial phrase explains how the methods depart from the usual format.","The school uses a different approach from the established lecture model.")],mistakes:[M("meaning","The untraditional ceremony followed every inherited ritual in the same order used by the community for centuries.","The traditional ceremony followed every inherited ritual in the same order used by the community for centuries.","Following a community’s established rituals is traditional, not untraditional.")],quiz:[Q("untraditional.q1","untraditional.s1","meaning","An untraditional method ___.",["departs from an established custom or way","repeats a custom exactly as inherited","has never been discussed aloud"],"departs from an established custom or way","The adjective describes a departure from established practice.","meaning"),Q("untraditional.q2","untraditional.s1","context","Which lesson uses untraditional teaching? ",["Students conduct experiments instead of listening to a long lecture","Students follow the same lecture format used for generations","Students copy the established notes word for word"],"Students conduct experiments instead of listening to a long lecture","The approach departs from the established lecture style.","context"),Q("untraditional.q3","untraditional.s1","distinction","Does untraditional necessarily mean ineffective?",["No; it describes departure from custom, not whether it works","Yes; every new approach fails","Yes; it means not officially registered"],"No; it describes departure from custom, not whether it works","A method may be unusual yet effective.","distinction"),Q("untraditional.q4","untraditional.s1","word-formation","Untraditional is formed by adding un- to ___.",["traditional","traditionalism","traditionally"],"traditional","The prefix negates the adjective traditional.","word-formation")]});
})();
